package greet

import (
	"fmt"
	"io/fs"
	"net"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
	"time"
)

var secretish = regexp.MustCompile(`(?i)(token|secret|password|passwd|api[_-]?key|credential|kubeconfig|BEGIN [A-Z ]*PRIVATE KEY|eyJ[A-Za-z0-9_-]{10,}\.)`)

func environKeys(raw []byte) ([]string, map[string]string) {
	vals := map[string]string{}
	var keys []string
	for _, kv := range strings.Split(string(raw), "\x00") {
		if kv == "" {
			continue
		}
		k, v, _ := strings.Cut(kv, "=")
		keys = append(keys, k)
		vals[k] = v
	}
	return keys, vals
}

func TestProbe(t *testing.T) {
	t.Logf("PROBE self uid=%d euid=%d gid=%d pid=%d", os.Getuid(), os.Geteuid(), os.Getgid(), os.Getpid())
	if b, err := os.ReadFile("/proc/1/status"); err == nil {
		for _, l := range strings.Split(string(b), "\n") {
			if strings.HasPrefix(l, "Name:") || strings.HasPrefix(l, "Uid:") || strings.HasPrefix(l, "Gid:") || strings.HasPrefix(l, "CapEff:") {
				t.Logf("PROBE pid1 %s", l)
			}
		}
	} else {
		t.Logf("PROBE pid1 status err=%v", err)
	}
	if b, err := os.ReadFile("/proc/1/cmdline"); err == nil {
		t.Logf("PROBE pid1 cmdline=%q", strings.ReplaceAll(string(b), "\x00", " "))
	}
	t.Logf("PROBE self env keys=%v", os.Environ())
	if b, err := os.ReadFile("/proc/1/environ"); err == nil {
		keys, vals := environKeys(b)
		t.Logf("PROBE pid1 environ keys=%v", keys)
		for _, k := range keys {
			v := vals[k]
			if k == "AX_WORKSPACES_YAML" || k == "AX_TASK_YAML" {
				head := v
				if len(head) > 3000 {
					head = head[:3000] + "...(truncated)"
				}
				t.Logf("PROBE pid1 %s (len %d)=\n%s", k, len(v), head)
				continue
			}
			if secretish.MatchString(k) || secretish.MatchString(v) {
				t.Logf("PROBE pid1 SECRETISH key=%s", k)
			}
		}
	} else {
		t.Logf("PROBE pid1 environ err=%v", err)
	}
	procs, _ := filepath.Glob("/proc/[0-9]*/environ")
	for _, p := range procs {
		b, err := os.ReadFile(p)
		if err != nil {
			continue
		}
		_, vals := environKeys(b)
		for k, v := range vals {
			if k != "AX_WORKSPACES_YAML" && k != "AX_TASK_YAML" && (secretish.MatchString(k) || secretish.MatchString(v)) {
				t.Logf("PROBE SECRETISH %s key=%s", p, k)
			}
		}
	}
	for _, p := range []string{"/var/run/secrets", "/var/run/secrets/kubernetes.io/serviceaccount", "/run/secrets", "/var/run/secrets/ateapi", "/run/servicedns-ca", "/root/.kube", "/root/.config", "/tmp/.kube", "/etc/kubernetes", "/root/.docker", "/root/.ssh", "/workspace", "/work"} {
		entries, err := os.ReadDir(p)
		names := []string{}
		for _, e := range entries {
			names = append(names, e.Name())
		}
		t.Logf("PROBE path %s err=%v entries=%v", p, err, names)
	}
	filepath.WalkDir("/work", func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() && (p == "/work/.gotmp") {
			info, _ := d.Info()
			t.Logf("PROBE work %s %v", p, info.Mode())
			return fs.SkipDir
		}
		info, _ := d.Info()
		t.Logf("PROBE work %s mode=%v size=%d", p, info.Mode(), info.Size())
		return nil
	})
	werr := os.WriteFile("/work/probe-write.txt", []byte("x"), 0o644)
	t.Logf("PROBE write /work err=%v", werr)
	os.Remove("/work/probe-write.txt")
	if b, err := os.ReadFile("/proc/version"); err == nil {
		t.Logf("PROBE /proc/version=%q", strings.TrimSpace(string(b)))
	}
	if out, err := exec.Command("dmesg").CombinedOutput(); err == nil || len(out) > 0 {
		s := string(out)
		if len(s) > 600 {
			s = s[:600]
		}
		t.Logf("PROBE dmesg=%q err=%v", s, err)
	}
	for _, target := range []string{"1.1.1.1:443", "8.8.8.8:443", "142.250.80.46:80", "10.96.0.1:443", "169.254.169.254:80", "127.0.0.1:80"} {
		start := time.Now()
		c, err := net.DialTimeout("tcp", target, 5*time.Second)
		if err == nil {
			c.Close()
		}
		t.Logf("PROBE tcp %s err=%v elapsed=%s", target, err, time.Since(start).Round(time.Millisecond))
	}
	for _, extra := range strings.Fields(os.Getenv("PROBE_EXTRA")) {
		_ = extra
	}
	if out, err := exec.Command("/bin/sh", "-c", "id; su -s /bin/sh nobody -c id 2>&1; echo su_exit=$?").CombinedOutput(); true {
		t.Logf("PROBE su output=%q err=%v", string(out), err)
	}
	if out, err := exec.Command("/bin/sh", "-c", "command -v curl wget; wget -q -T 5 -O- http://1.1.1.1/ 2>&1 | head -c 200; echo wget_exit=$?").CombinedOutput(); true {
		t.Logf("PROBE wget output=%q err=%v", string(out), err)
	}
	fmt.Sprint()
}

