func TestEgressHTTP(t *testing.T) {
	client := &http.Client{Timeout: 5 * time.Second}
	for _, u := range []string{"http://1.1.1.1/", "http://142.250.80.46/", "https://1.1.1.1/"} {
		start := time.Now()
		resp, err := client.Get(u)
		if err != nil {
			t.Logf("EGRESS %s err=%v elapsed=%s", u, err, time.Since(start).Round(time.Millisecond))
			continue
		}
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 80))
		resp.Body.Close()
		t.Logf("EGRESS %s status=%d body=%q elapsed=%s", u, resp.StatusCode, body, time.Since(start).Round(time.Millisecond))
	}
	out, err := exec.Command("/bin/sh", "-c", "which curl || echo no-curl; for u in http://1.1.1.1/ http://142.250.80.46/; do wget -q -T 5 -O- $u 2>&1 | head -c 200; echo \" wget_rc=$?\"; done").CombinedOutput()
	t.Logf("EGRESS shell=%q err=%v", string(out), err)
}

