func TestEgressData(t *testing.T) {
	for _, target := range []string{"1.1.1.1:80", "142.250.80.46:80", "10.96.0.1:443", "10.96.38.5:8080", "10.96.236.222:80"} {
		start := time.Now()
		c, err := net.DialTimeout("tcp", target, 5*time.Second)
		if err != nil {
			t.Logf("EGRESS %s dial err=%v elapsed=%s", target, err, time.Since(start).Round(time.Millisecond))
			continue
		}
		c.SetDeadline(time.Now().Add(5 * time.Second))
		_, werr := io.WriteString(c, "GET / HTTP/1.0\r\nHost: probe\r\n\r\n")
		buf := make([]byte, 64)
		n, rerr := c.Read(buf)
		c.Close()
		t.Logf("EGRESS %s dial ok write_err=%v read_bytes=%d read_err=%v first=%q elapsed=%s", target, werr, n, rerr, buf[:n], time.Since(start).Round(time.Millisecond))
	}
}

